useEffect(() => {
  if (!user) return;
  api
    .get('/api/pledges')
    .then(({ data }) => Array.isArray(data?.items) && setPledges(data.items as Pledge[]))
    .catch(() => undefined);
}, [user]);
useEffect(() => {
  const h = window.setInterval(() => setPgNow(Date.now()), 30000);
  return () => window.clearInterval(h);
}, []);
// Einsätze auswerten: geschafft (mit Beweis) oder Frist verpasst
useEffect(() => {
  if (!user) return;
  for (const pl of pledges) {
    if (pl.status !== 'active') continue;
    const t = tasks.find(x => x.id === pl.taskId);
    const dlDay = iso(new Date(pl.deadline));
    const fromDay = iso(new Date(pl.createdAt));
    const okDay = t
