      : undefined;
    const st = okDay ? 'kept' : pgNow > Date.parse(pl.deadline) ? 'failed' : '';
    if (!st) continue;
    api
      .post('/api/pledge/resolve', { id: pl.id, status: st })
      .then(({ data }) => {
        if (!data?.pledge) return;
        setPledges(v => v.map(x => (x.id === pl.id ? (data.pledge as Pledge) : x)));
