            : 'Frist verpasst: „' + pl.task + '“. Fällig wären ' + euro(pl.amount) + ' (Testphase – nichts abgebucht).'
        );
      })
      .catch(() => undefined);
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [pledges, tasks, pgNow, user]);
const preparePledge = (taskId: string, text: string, proof: boolean): string => {
