    return taskId;
  }
  const t: Task = {
    id: uid(),
    text: text.slice(0, 200),
    date: today,
    time: '',
    imp: true,
    urg: false,
    rep: 'none',
    cat: guessArea(text, metaRef.current).id,
    done: {},
    proof,
  };
  commit([...cur, t]);
  return t.id;
};

